export const worldCapitalDestinations: Destination[] = worldCapitalSeeds.map((seed) => ({
  place: placeSummarySchema.parse({
    id: seed.id,
    name: seed.capital,
    countryCode: seed.countryCode,
    latitude: seed.latitude,
    longitude: seed.longitude,
    locale: 'en',
    timeZone: seed.timeZone,
    currency: seed.currency,
    updatedAt: '2026-10-21T00:00:00.000Z',
    sourceLabel: 'World Cities dataset (CC BY 4.0)',
  }),
  nameZh: '',
  region: seed.countryName,
  regionCode: seed.regionCode,
  regionGroup: 'rest-of-world',
  aliases: [...seed.aliases],
  summary: `${seed.capital} is the capital of ${seed.countryName}. Explore the city on the map, then build a route from local notes and official visitor information.`,
  isCapital: true,
  capitalOf: seed.countryName,
}));

export const worldCapitals = worldCapitalDestinations;
